175	}
176	
177	function findAdminLogins(
178	  repo: string,
179	  comments: ApiComment[],
180	  command: string,
181	  proofUpdatedAt: string
182	): Set<string> {
183	  const proofTime = Date.parse(proofUpdatedAt);
184	  const candidates = new Set(
185	    comments
186	      .filter(
187	        (comment) =>
188	          comment.body.trim() === command &&
189	          Date.parse(comment.created_at) > proofTime &&
190	          comment.user?.login
191	      )
192	      .map((comment) => comment.user?.login as string)
193	  );
194	  const admins = new Set<string>();
195	  for (const login of candidates) {
196	    try {
197	      const permission = ghApi<{ permission?: string }>(
198	        `repos/${repo}/collaborators/${login}/permission`
199	      );
200	      if (permission.permission === "admin") admins.add(login);
201	    } catch {
202	      // A missing collaborator or unreadable permission is not approval.
203	    }
204	  }
