208	function openPullRequest(url: string): void {
209	  const command = process.platform === "darwin" ? "open" : "xdg-open";
210	  const result = spawnSync(command, [url], { stdio: "ignore" });
211	  if (result.status !== 0) {
212	    console.warn(`Could not open the browser automatically. Open ${url}`);
213	  }
214	}
215	
216	function parentCommentBody(
217	  state: "pending" | "success",
218	  proof: UiReviewProof,
219	  proofUrl: string,
220	  approvalUrl: string | null,
221	  lobuHead: string
222	): string {
223	  const headline =
224	    state === "success" ? "UI review approved" : "UI review awaiting approval";
225	  const approvalLine = approvalUrl
226	    ? `- Approval: ${approvalUrl}`
227	    : `- Approval command: \`${approvalCommand(proof.owletto_sha)}\``;
228	  return `${PARENT_MARKER}
229	**${headline}** for Lobu head \`${lobuHead}\`.
230	
231	- Owletto range: \`${proof.lobu_base_owletto_sha}\` → \`${proof.owletto_sha}\`
232	- Proof and approval thread: ${proofUrl}
233	${approvalLine}`;
234	}
235	
236	function main(): number {
237	  const options = parseOptions(process.argv.slice(2));
238	  const localHead = run("git", ["rev-parse", "HEAD"]);
239	  const lobuRepo = run("gh", [
240	    "repo",
241	    "view",
242	    "--json",
243	    "nameWithOwner",
244	    "-q",
245	    ".nameWithOwner",
246	  ]);
247	  const parentPr = jsonCommand<PullRequestView>("gh", [
248	    "pr",
249	    "view",
250	    "--json",
251	    "number,url,baseRefOid,headRefOid",
252	  ]);
253	  if (parentPr.headRefOid !== localHead) {
254	    throw new Error(
255	      `local HEAD ${localHead} is not PR #${parentPr.number} head ${parentPr.headRefOid}; update the branch first`
256	    );
257	  }
258	  postStatus(
259	    lobuRepo,
260	    localHead,
261	    "pending",
262	    "UI review in progress",
263	    parentPr.url
264	  );
265	
266	  const owlettoRemote = run("git", [
267	    "config",
268	    "-f",
269	    ".gitmodules",
270	    "--get",
271	    "submodule.packages/owletto.url",
272	  ]);
273	  const owlettoRepo = githubRepoFromRemote(owlettoRemote);
274	
275	  const basePointer = getPointer(lobuRepo, parentPr.baseRefOid);
276	  const headPointer = getPointer(lobuRepo, parentPr.headRefOid);
277	  if (basePointer === headPointer) {
278	    const parentComment = findComment(lobuRepo, parentPr.number, PARENT_MARKER);
279	    if (parentComment) {
280	      ghApi(`repos/${lobuRepo}/issues/comments/${parentComment.id}`, "PATCH", {
281	        body: `${PARENT_MARKER}
282	**UI review not applicable** for Lobu head \`${localHead}\`.
283	
284	\`packages/owletto\` remains at \`${headPointer}\`.`,
285	      });
286	    }
287	    postStatus(
288	      lobuRepo,
289	      localHead,
290	      "success",
291	      "No Owletto pointer change",
292	      parentPr.url
293	    );
294	    console.log(
295	      `ui-review: not applicable; packages/owletto remains ${headPointer}`
296	    );
297	    return 0;
298	  }
299	
300	  const pulls = ghApi<OwlettoPullRequest[]>(
301	    `repos/${owlettoRepo}/commits/${headPointer}/pulls`
302	  );
303	  const owlettoPr = selectOwlettoPullRequest(pulls, headPointer);
304	  if (!owlettoPr) {
305	    postStatus(
306	      lobuRepo,
307	      localHead,
308	      "error",
309	      "Owletto pointer is not an exact merged PR squash commit",
310	      parentPr.url
311	    );
312	    throw new Error(
313	      `Owletto ${headPointer} is not the squash commit of a merged ${owlettoRepo} PR`
314	    );
315	  }
316	
317	  let comments = ghApiPages<ApiComment>(
318	    `repos/${owlettoRepo}/issues/${owlettoPr.number}/comments`
319	  );
320	  let proofComment = comments.find((comment) =>
321	    comment.body.startsWith(PROOF_MARKER)
322	  );
323	  let currentProof = proofComment ? parseProof(proofComment.body) : null;
324	  const exactProof =
325	    currentProof &&
326	    proofMatches(
327	      currentProof,
328	      lobuRepo,
329	      basePointer,
330	      headPointer,
331	      parentPr.number,
332	      owlettoPr.number
333	    );
334	
335	  if (
336	    !exactProof ||
337	    (options.artifactUrl && currentProof?.artifact_url !== options.artifactUrl)
338	  ) {
339	    if (!options.artifactUrl) {
340	      postStatus(
341	        lobuRepo,
342	        localHead,
343	        "error",
344	        "UI proof missing; rerun make ui-review with ARTIFACT=...",
345	        owlettoPr.html_url
346	      );
347	      if (options.open) openPullRequest(owlettoPr.html_url);
348	      throw new Error(
349	        `No current proof on ${owlettoPr.html_url}. Rerun with ARTIFACT=<hosted HTTPS comparison>.`
350	      );
351	    }
352	
353	    currentProof = {
354	      version: 1,
355	      lobu_repo: lobuRepo,
356	      lobu_pr: parentPr.number,
357	      lobu_base_owletto_sha: basePointer,
358	      owletto_sha: headPointer,
359	      owletto_pr: owlettoPr.number,
360	      artifact_url: options.artifactUrl,
361	    };
362	    proofComment = upsertComment(
363	      owlettoRepo,
364	      owlettoPr.number,
365	      PROOF_MARKER,
366	      buildProofBody(currentProof)
367	    );
368	    comments = ghApiPages<ApiComment>(
369	      `repos/${owlettoRepo}/issues/${owlettoPr.number}/comments`
370	    );
371	  }
372	
373	  if (!currentProof || !proofComment) {
374	    throw new Error("UI proof publication did not return a usable comment");
375	  }
376	
377	  const command = approvalCommand(headPointer);
378	  const adminLogins = findAdminLogins(
379	    owlettoRepo,
380	    comments,
381	    command,
382	    proofComment.updated_at
383	  );
384	  const approval = findApproval(
385	    comments,
386	    headPointer,
387	    proofComment.updated_at,
388	    adminLogins
389	  );
390	  const state = approval ? "success" : "pending";
391	  const description = approval
392	    ? `UI approved for Owletto ${headPointer.slice(0, 9)}`
393	    : `Awaiting UI approval for Owletto ${headPointer.slice(0, 9)}`;
394	
395	  upsertComment(
396	    lobuRepo,
397	    parentPr.number,
398	    PARENT_MARKER,
399	    parentCommentBody(
400	      state,
401	      currentProof,
402	      proofComment.html_url,
403	      approval?.html_url ?? null,
404	      localHead
405	    )
406	  );
407	  postStatus(lobuRepo, localHead, state, description, proofComment.html_url);
408	
409	  if (approval) {
410	    console.log(
411	      `ui-review: approved by ${approval.user?.login} at ${approval.html_url}`
412	    );
413	    return 0;
414	  }
415	
416	  console.log(`ui-review: awaiting an admin comment on ${owlettoPr.html_url}`);
417	  console.log(command);
418	  if (options.open) openPullRequest(owlettoPr.html_url);
419	  return 3;
420	}
421	
422	if (import.meta.main) {
423	  try {
424	    process.exitCode = main();
425	  } catch (error) {
426	    console.error(error instanceof Error ? error.message : String(error));
427	    process.exitCode = 2;
428	  }
429	}
