// Offer a chip only when it would actually narrow to something — same rule
// as the connectors page. "All" stays whenever there is more than one real
// choice.
const chipKeys = useMemo<AgentFilter[]>(() => {
	const live: AgentFilter[] = [];
	if (allItems.some((item) => item.kind === "managed")) {
		live.push("managed");
	}
	if (allItems.some((item) => item.kind === "connected")) {
		live.push("connected");
	}
	return live.length > 1 ? (["all", ...live] as AgentFilter[]) : [];
}, [allItems]);

const [filter, setFilter] = useState<AgentFilter>("all");
// A chip can disappear under an active filter (last managed agent removed,
// an app's device paired). Fall back to "all" instead of filtering to an
// empty page with no chip left to clear it.
const activeFilter =
	chipKeys.length === 0 || chipKeys.includes(filter) ? filter : "all";

const items = useMemo(
	() =>
		allItems.filter((item) => {
			if (activeFilter === "all") return true;
			if (activeFilter === "managed") return item.kind === "managed";
			return item.kind === "connected";
		}),
	[allItems, activeFilter],
);

const mcpUrl = buildMcpUrl(owner);
const onboardingPrompt = buildAgentOnboardingPrompt({
	workspaceName,
	owner,
	mcpUrl,
});

const isContentLoading =
	isWorkspaceLoading || isOrgLoading || isAgentsLoading;

return (
	<div className="space-y-4">
		{/* One control row: chips left, actions right — same line, mirroring
		    the connectors page. The copy-prompt action is just a button; the
		    prompt itself only exists on the clipboard. */}
		<div className="flex flex-wrap items-center gap-x-3 gap-y-2">
			<div className="flex min-w-0 flex-1 flex-wrap items-center gap-1.5">
				{chipKeys.map((key) => (
					<Button
						key={key}
						type="button"
						variant={activeFilter === key ? "secondary" : "ghost"}
						aria-pressed={activeFilter === key}
						size="sm"
						className="h-7 px-2 text-xs"
						onClick={() => setFilter(key)}
					>
						{AGENT_FILTER_LABELS[key]}
					</Button>
				))}
			</div>
			<div className="ml-auto flex shrink-0 items-center gap-2">
				<CopyPromptButton text={onboardingPrompt} />
				<Button asChild size="sm" className="h-8 text-xs">
					<Link
						to="/$owner/agents/new"
						params={{ owner }}
						search={{ run_id: undefined }}
					>
						<Plus className="mr-1.5 h-3.5 w-3.5" />
						Build a managed agent
					</Link>
				</Button>
			</div>
		</div>

		{isContentLoading ? (
			<div
				className="overflow-hidden rounded-lg border"
				role="status"
				aria-label="Loading agents"
			>
				{Array.from({ length: 4 }).map((_, i) => (
					<div
						// biome-ignore lint/suspicious/noArrayIndexKey: static skeleton rows
						key={i}
						className={`flex items-center gap-3 px-3 py-2.5 ${
							i === 3 ? "" : "border-b"
						}`}
					>
						<Skeleton className="h-7 w-7 shrink-0 rounded-md" />
						<div className="min-w-0 flex-1 space-y-1.5">
							<Skeleton className="h-4 w-40" />
							<Skeleton className="h-3 w-24" />
						</div>
					</div>
				))}
			</div>
		) : items.length === 0 ? (
			<TabEmptyState
				icon={OWNER_SECTIONS.agents.icon}
				title={
					!canManage
						? "Workspace membership required"
						: activeFilter === "managed"
							? "No managed agents yet"
							: "No agents match this filter"
				}
				description={
					!canManage
						? "Only workspace members can manage agents here."
						: activeFilter === "managed"
							? "Build one, or connect an agent you already run."
							: "Try another filter."

const rowCount = items.length;

// What you could still connect: the Mac app, the extension, the CLI, an
// MCP client. Shown under the unfiltered list — each one drops off the
// section as soon as it has paired something.
const appEntries = useMemo(
	() => (filter === "all" ? offerableConnectorApps(ownerSlug, devices) : []),
	[filter, ownerSlug, devices],
);
// The last connector row keeps its divider while the setup offers follow
// it on the page — the bordered list reads as one inventory.
const visibleEntryCount = rowCount + appEntries.length;

const addConnector = (
	<Button asChild size="sm" className="h-8 shrink-0 text-xs">
		<Link to="/$owner/connectors/create" params={{ owner: ownerSlug }}>
			<Plus className="mr-1.5 h-3.5 w-3.5" />
			Add connector
		</Link>
	</Button>
);

// Reserved-footprint skeleton — the same bordered row list the loaded page
// uses, so nothing reflows when the groups land.
if (isContentLoading) {
	return (
		<div className="space-y-4">
			<div className="flex justify-end">{addConnector}</div>
			<div
				className="overflow-hidden rounded-lg border"
				role="status"
				aria-label="Loading connectors"
			>
				{Array.from({ length: 6 }).map((_, i) => (
					<div
						// biome-ignore lint/suspicious/noArrayIndexKey: static skeleton rows
						key={i}
						className={`flex items-center gap-3 px-3 py-2.5 ${
							i === 5 ? "" : "border-b"
						}`}

