import { HttpResponse, http } from "msw";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { renderRoute } from "@/test/render";

const CLAUDE_DESKTOP = {
	id: "claude-desktop",
	kind: "mcp",
	title: "Claude Desktop",
	registrationGroupKey: "claude-desktop",
	status: "connected",
	authState: "authorized",
	lastSeenAt: 1,
};

// Per-test so the empty workspace can be exercised — the fresh-install case is
// the one that regressed. Reassigned before render, never mid-render.
let mockClients: unknown[] = [CLAUDE_DESKTOP];

// The landing page's connected-apps section is the old connectors "Agents"
// inventory filter, which moved here when Agents became its own nav section.
vi.mock("@/lib/api/clients", () => ({
	useConnectedClients: () => ({ data: mockClients }),
}));

beforeEach(() => {
	mockClients = [CLAUDE_DESKTOP];
});

describe("agents landing page", () => {
	it("lists managed agents and connected apps and offers the onboarding prompt", async () => {
		// getPathScope reads window.location, so pin it to the route under test.
		const previousUrl = window.location.pathname + window.location.search;
		window.history.replaceState({}, "", "/test-org/agents");
		let unmount: (() => void) | undefined;
		try {
			const result = await renderRoute(
				"/test-org/agents",
				{
					authenticated: true,
					extraHandlers: [
					http.post("*/api/:slug/resolve_path", () =>
						HttpResponse.json({
							workspace: {
								id: "org-1",
								slug: "test-org",
								name: "Test Org",
								type: "organization",
							},
							segments: [],
							path: [],
							entity: null,
							children: [],
							siblings: [],
							bootstrap: null,
						}),
					),
					http.get("*/api/organizations", () =>
						HttpResponse.json({
							organizations: [
								{
									id: "org-1",
									name: "Test Org",
									slug: "test-org",
									logo: null,
									description: null,
									created_at: "2026-01-01T00:00:00.000Z",
									is_member: true,
									visibility: "private",
								},
							],
						}),
					),
					http.get("*/api/:slug/agents", () =>
						HttpResponse.json({
							agents: [
								{
									agentId: "agent-a",
									name: "Alpha",
									description: undefined,
									owner: { platform: "web", userId: "user-1" },
									createdAt: 1,
									connectionCount: 2,
									activeConnectionCount: 1,
									clientCount: 0,
									behaviorCount: 1,
									userCount: 3,
									platforms: [],
									providers: [],
									status: "active",
								},
							],
						}),
					),
				],
			});
			unmount = result.unmount;

			// No page header — the page opens straight into the chips + list,
			// like the connectors page.
			expect(result.queryByRole("heading", { name: "Agents" })).toBeNull();
			// Managed roster row links into the agent's chat.
			const alpha = await result.findByRole("link", { name: /Alpha/ });
			expect(alpha).toHaveAttribute("href", "/test-org/agents/agent-a/chat");
			// Connected external agent (moved from the connectors Agents filter).
			expect(await result.findByText("Claude Desktop")).toBeInTheDocument();
			// The build CTA links to the new-agent form.
			expect(
				result.getAllByText("Build a managed agent").length,
			).toBeGreaterThan(0);

			// One filterable list, connectors-style: the Managed chip narrows to
			// the roster, Connected to the apps, All restores both.
			expect(
				await result.findByRole("button", { name: "Managed" }),
			).toHaveAttribute("aria-pressed", "false");
			result.getByRole("button", { name: "Connected" });
			expect(
				result.queryByRole("heading", { name: "Connected apps" }),
			).toBeNull();
			expect(
				result.queryByRole("heading", { name: "Managed agents" }),
			).toBeNull();

			result.getByRole("button", { name: "Managed" }).click();
			expect(
				await result.findByRole("link", { name: /Alpha/ }),
			).toBeInTheDocument();
			expect(result.queryByText("Claude Desktop")).toBeNull();

			result.getByRole("button", { name: "Connected" }).click();
			expect(
				await result.findByText("Claude Desktop"),
			).toBeInTheDocument();
			expect(result.queryByRole("link", { name: /Alpha/ })).toBeNull();
		} finally {
			unmount?.();
			window.history.replaceState({}, "", previousUrl);
		}
	}, 30_000);

	it("offers a copy-prompt button for connecting an existing agent", async () => {
		// getPathScope reads window.location, so pin it to the route under test.
		const previousUrl = window.location.pathname + window.location.search;
		window.history.replaceState({}, "", "/test-org/agents");
		let unmount: (() => void) | undefined;
		try {
			const result = await renderRoute("/test-org/agents", {
				authenticated: true,
				extraHandlers: [
				http.post("*/api/:slug/resolve_path", () =>
					HttpResponse.json({
						workspace: {
							id: "org-1",
							slug: "test-org",
							name: "Test Org",
							type: "organization",
						},
						segments: [],
						path: [],
						entity: null,
						children: [],
						siblings: [],
						bootstrap: null,
					}),
				),
				http.get("*/api/organizations", () =>
					HttpResponse.json({
						organizations: [
							{
								id: "org-1",
								name: "Test Org",
								slug: "test-org",
								logo: null,
								description: null,
								created_at: "2026-01-01T00:00:00.000Z",
								is_member: true,
								visibility: "private",
							},
						],
					}),
				),
				http.get("*/api/:slug/agents", () =>
					HttpResponse.json({ agents: [] }),
				),
			],
		});
			unmount = result.unmount;

			expect(
				await result.findByRole("button", { name: "Copy prompt" }),
			).toBeInTheDocument();
			expect(
				result.getByRole("link", { name: "Build a managed agent" }),
			).toHaveAttribute("href", "/test-org/agents/new");
		} finally {
			unmount?.();
			window.history.replaceState({}, "", previousUrl);
		}
	}, 30_000);
});

