						children: [],
						siblings: [],
						bootstrap: null,
					}),
				),
				http.get("*/api/organizations", () =>
					HttpResponse.json({
						organizations: [
							{
								id: "org-1",
								name: "Test Org",
								slug: "test-org",
								logo: null,
								description: null,
								created_at: "2026-01-01T00:00:00.000Z",
								is_member: true,
								visibility: "private",
							},
						],
					}),
				),
				http.get("*/api/:slug/agents", () =>
					HttpResponse.json({ agents: [] }),
				),
			],
		});
			unmount = result.unmount;

			expect(
				await result.findByRole("button", { name: "Copy prompt" }),
			).toBeInTheDocument();
			expect(
				result.getByRole("link", { name: "Build a managed agent" }),
			).toHaveAttribute("href", "/test-org/agents/new");
		} finally {
			unmount?.();
			window.history.replaceState({}, "", previousUrl);
		}
	}, 30_000);

	it("points a fresh workspace at the MCP endpoint instead of blaming a filter", async () => {
		// A brand-new install: no managed agents, nothing connected. Filter chips
		// only render when more than one kind exists, so this page has none — any
		// "try another filter" copy sends people hunting for a control that is
		// not on the page.
		mockClients = [];
		const previousUrl = window.location.pathname + window.location.search;
		window.history.replaceState({}, "", "/test-org/agents");
		let unmount: (() => void) | undefined;
		try {
			const result = await renderRoute("/test-org/agents", {
				authenticated: true,
				extraHandlers: [
					http.post("*/api/:slug/resolve_path", () =>
						HttpResponse.json({
							workspace: {
								id: "org-1",
								slug: "test-org",
								name: "Test Org",
								type: "organization",
