}: {
	owner: string;
	organizationId: string | null;
	isWorkspaceLoading: boolean;
}) {
	const [facets, setFacets] = useState<BehaviorFacets>(DEFAULT_FACETS);
	const behaviorsQuery = useBehaviorsList(organizationId ?? undefined);
	const { data: agents = [] } = useAgents({ enabled: !!organizationId });
	const { data: devices = [] } = useDevices();
	// Same catalog source as the Connectors page, so marks resolve identically.
	const { data: connectorDefinitions = [] } =
		useInstallableConnectorCatalog(organizationId);
	const deleteBehavior = useDeleteBehavior();

	const agentNames = useMemo(() => {
		const map = new Map<string, string>();
		for (const agent of agents) map.set(agent.agentId, agent.name);
		return map;
	}, [agents]);

	const deviceLabels = useMemo(() => {
		const map = new Map<string, string>();
		for (const device of devices) {
			map.set(device.id, device.label || device.platform || device.id);
		}
		return map;
	}, [devices]);

	const behaviors = useMemo(
		() => mergeBehaviors(behaviorsQuery.data ?? []),
		[behaviorsQuery.data],
	);
	const visible = useMemo(
		() => filterBehaviors(behaviors, facets),
		[behaviors, facets],
	);

	const isLoading = isWorkspaceLoading || behaviorsQuery.isLoading;

	const newBehavior = (
		<Button asChild size="sm" className="h-8 shrink-0 text-xs">
			<Link to="/$owner/behaviors/new" params={{ owner }}>
				<Plus className="mr-1.5 h-3.5 w-3.5" />
				New behavior
			</Link>
		</Button>
	);

	// Reserved-footprint skeleton — the same bordered row list the loaded page
	// uses, so nothing reflows when the data lands.
	if (isLoading) {
		return (
			<div className="space-y-4">
				<div className="flex justify-end">{newBehavior}</div>
				<div
					className="overflow-hidden rounded-lg border"
					role="status"
					aria-label="Loading behaviors"
				>
					{Array.from({ length: 4 }).map((_, i) => (
						<div
							// biome-ignore lint/suspicious/noArrayIndexKey: static skeleton rows
							key={i}
							className={`flex items-center gap-3 px-3 py-2.5 ${
								i === 3 ? "" : "border-b"
							}`}
						>
							<Skeleton className="h-7 w-7 shrink-0 rounded-md" />
							<div className="min-w-0 flex-1 space-y-1.5">
								<Skeleton className="h-4 w-40" />
								<Skeleton className="h-3 w-24" />
							</div>
						</div>
					))}
				</div>
			</div>
		);
	}

	return (
		<div className="space-y-4">
			<p className="text-sm text-muted-foreground">
				Everything that runs on its own — agent-owned or agentless, across
				all entities.
			</p>
			<div className="flex flex-wrap items-center gap-x-3 gap-y-2">
				<div className="flex min-w-0 flex-1 flex-wrap items-center gap-1.5">
					{KIND_FACETS.map((option) => (
						<Button
							key={option.value}
							type="button"
							variant={facets.kind === option.value ? "secondary" : "ghost"}
							aria-pressed={facets.kind === option.value}
							size="sm"
							className="h-7 px-2 text-xs"
							onClick={() =>
								setFacets((current) => ({ ...current, kind: option.value }))
							}
						>
							{option.label}
						</Button>
					))}
				</div>
				<div className="ml-auto shrink-0">{newBehavior}</div>
			</div>

			{behaviors.length === 0 ? (
				<TabEmptyState
					icon={Radio}
					title="No behaviors yet"
					description="Behaviors act on their own — reply to a message, run a nightly summary, react to a ticket. Use New behavior to create one."
				/>
