// Chips only when they would actually narrow — the rule Connectors and
// Agents already use. A workspace with one trigger kind (or none) got four
// buttons that could only ever narrow to nothing, and an empty page then
// blamed a filter the reader had never touched.
const kindFacets = useMemo(() => {
	const kinds = new Set(behaviors.map((behavior) => behavior.kind));
	return kinds.size > 1
		? KIND_FACETS.filter(
				(option) => option.value === "all" || kinds.has(option.value),
			)
		: [];
}, [behaviors]);

const isLoading = isWorkspaceLoading || behaviorsQuery.isLoading;

