// @vitest-environment jsdom
import { render, screen } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@tanstack/react-router", () => ({
	Link: ({
		children,
		to,
		params,
	}: {
		children?: React.ReactNode;
		to: string;
		params?: Record<string, string>;
	}) => (
		<a
			href={to
				.replace("$owner", params?.owner ?? "")
				.replace("$agentId", params?.agentId ?? "")
				.replace("$behaviorId", params?.behaviorId ?? "")}
		>
			{children}
		</a>
	),
}));

// One agent-owned behavior and one agentless behavior. The org-wide page must
// deep-link the agent-owned one to the workbench and the agentless one to the
// workspace detail route.
const records = [
	{
		behavior_id: "101",
		name: "Nightly digest",
		status: "active",
		created_at: "2026-01-01T00:00:00Z",
		updated_at: "2026-01-01T00:00:00Z",
		next_run_at: null,
		last_fired_at: null,
		agent_id: "agent-a",
		triggers: [{ kind: "schedule", cron: "0 9 * * *" }],
		entity_id: 1,
		entity_type: "project",
		entity_name: "Apollo",
		entity_slug: "apollo",
	},
	{
		behavior_id: "202",
		name: "Inbox triage",
		status: "active",
		created_at: "2026-01-02T00:00:00Z",
		updated_at: "2026-01-02T00:00:00Z",
		next_run_at: null,
		last_fired_at: null,
		agent_id: null,
		device_worker_id: "device-9",
		triggers: [{ kind: "schedule", cron: "0 10 * * *" }],
		entity_id: 2,
		entity_type: "lead",
		entity_name: "Pipeline",
		entity_slug: "pipeline",
	},
];

// Per-test so the fresh-workspace case can be exercised. Reset in beforeEach.
let mockRecords: unknown[] = records;

vi.mock("@/hooks/use-behaviors", () => ({
	useBehaviorsList: () => ({ data: mockRecords, isLoading: false }),
	useDeleteBehavior: () => ({
		isPending: false,
		mutate: vi.fn(),
	}),
}));

vi.mock("@/lib/api/agents", () => ({
	useAgents: () => ({ data: [{ agentId: "agent-a", name: "Apollo Agent" }] }),
}));

vi.mock("@/lib/api/connections", () => ({
	useDevices: () => ({
		data: [{ id: "device-9", label: "Burak's Mac", platform: "darwin" }],
	}),
	useInstallableConnectorCatalog: () => ({ data: [] }),
}));

vi.mock("@/lib/api/clients", () => ({
	useConnectedClients: () => ({ data: [] }),
}));

import { BehaviorsPage } from "./behaviors-page";

describe("BehaviorsPage (workspace-level)", () => {
	beforeEach(() => {
		mockRecords = records;
	});

	it("offers trigger chips only once more than one kind exists", () => {
		// Both fixture behaviors are schedules, so a Schedule chip could only
		// ever narrow to everything and an Event chip to nothing.
		const { unmount } = render(
			<BehaviorsPage
				owner="acme"
				organizationId="org-1"
				isWorkspaceLoading={false}
			/>,
		);
		expect(screen.queryByRole("button", { name: "Schedule" })).toBeNull();
		unmount();

		// Add a second kind and narrowing becomes a real choice — but only the
		// kinds that exist earn a chip, so Manual still stays off the row.
		mockRecords = [
			...records,
			{
				...(records[0] as Record<string, unknown>),
				behavior_id: "303",
				name: "Slack replies",
				triggers: [{ kind: "event", event: "message.created" }],
			},
		];
		render(
			<BehaviorsPage
				owner="acme"
				organizationId="org-1"
				isWorkspaceLoading={false}
			/>,
		);
		expect(screen.getByRole("button", { name: "All" })).toBeTruthy();
		expect(screen.getByRole("button", { name: "Schedule" })).toBeTruthy();
		expect(screen.getByRole("button", { name: "Event" })).toBeTruthy();
		expect(screen.queryByRole("button", { name: "Manual" })).toBeNull();
	});

	it("drops the chips on a fresh workspace instead of offering dead filters", () => {
		// Four buttons that can only ever narrow to nothing, over an empty page
		// that then blames a filter the reader never touched.
		mockRecords = [];
		render(
			<BehaviorsPage
				owner="acme"
				organizationId="org-1"
				isWorkspaceLoading={false}
			/>,
		);
		for (const label of ["All", "Event", "Schedule", "Manual"]) {
			expect(screen.queryByRole("button", { name: label })).toBeNull();
		}
		expect(screen.getByText("No behaviors yet")).toBeTruthy();
		expect(screen.queryByText(/match this filter/i)).toBeNull();
	});

	it("renders the section header and every org behavior", () => {
		render(
			<BehaviorsPage
				owner="acme"
				organizationId="org-1"
				isWorkspaceLoading={false}
			/>,
		);
		expect(
			screen.getByText(/Everything that runs on its own/),
		).toBeTruthy();
		expect(screen.getByText(/Nightly digest/)).toBeTruthy();
		expect(screen.getByText(/Inbox triage/)).toBeTruthy();
	});

	it("links the agent-owned behavior to the workspace detail route", () => {
		render(
			<BehaviorsPage
				owner="acme"
				organizationId="org-1"
				isWorkspaceLoading={false}
			/>,
		);
		const detail = screen
			.getAllByRole("link")
			.map((a) => a.getAttribute("href"))
			.filter((href) => href?.includes("/acme/behaviors/101"));
		expect(detail.length).toBeGreaterThan(0);
		// No lingering agent-workbench deep links — Behaviors is one section.
		const workbench = screen
			.getAllByRole("link")
			.map((a) => a.getAttribute("href"))
			.filter((href) => href?.includes("/agents/agent-a/behaviors"));
		expect(workbench.length).toBe(0);
	});

	it("links the agentless behavior to the workspace detail route", () => {
		render(
			<BehaviorsPage
				owner="acme"
				organizationId="org-1"
				isWorkspaceLoading={false}
			/>,
		);
		const workspace = screen
			.getAllByRole("link")
			.map((a) => a.getAttribute("href"))
			.filter((href) => href === "/acme/behaviors/202");
		expect(workspace.length).toBeGreaterThan(0);
	});

	it("shows the executor and never invents an agent for an agentless behavior", () => {
		render(
			<BehaviorsPage
				owner="acme"
				organizationId="org-1"
				isWorkspaceLoading={false}
			/>,
		);
		// The agent-owned behavior resolves its agent's name; the device-pinned
		// one surfaces the device, not a phantom agent.
		expect(screen.getByText("Apollo Agent")).toBeTruthy();
		expect(screen.getByText("Burak's Mac")).toBeTruthy();
	});
});

