/**
 * The workspace's agents, in one place: the managed agents Lobu runs and the
 * agents that connect to it. One filterable list, mirroring the connectors
 * page — chips narrow the inventory, the two actions sit on the same row.
 */

/** The copyable prompt pasted into an existing agent to onboard it to Lobu. */
export function buildAgentOnboardingPrompt(params: {
	workspaceName: string;
	owner: string;
	mcpUrl: string;
}): string {
	const { workspaceName, owner, mcpUrl } = params;
	return [
		`You are being connected to the "${workspaceName}" Lobu workspace (${owner}).`,
		"",
		"Connect to it over MCP so you can read and write the workspace's shared",
		"memory, run its connectors, and execute Behaviors. Add this endpoint to",
		"your MCP configuration:",
		"",
		mcpUrl,
		"",
		"If your client configures MCP from the command line:",
		`  claude mcp add --transport http lobu ${mcpUrl}`,
		`  codex mcp add lobu --url ${mcpUrl}`,
		`  gemini mcp add --transport http lobu ${mcpUrl}`,
		"",
		"Authenticate when prompted — you connect as a member of the workspace.",
		"",
		"Once connected:",
		"- search_memory recalls workspace memory; save_memory persists it. Save",
		"  anything the user asks you to remember.",
		"- search_sdk discovers the current SDK methods, connector feeds, and",
		"  operations — call it before guessing a capability.",
		"- query_sdk reads, run_sdk mutates. Never fabricate a returned URL or",
		"  identifier.",
	].join("\n");
}

function CopyPromptButton({ text }: { text: string }) {
	const [copied, setCopied] = useState(false);
	return (
		<Button
			variant="outline"
			size="sm"
			className="h-8 text-xs"
			onClick={() => {
				if (typeof navigator === "undefined" || !navigator.clipboard) return;
				void navigator.clipboard.writeText(text).then(() => {
					setCopied(true);
					setTimeout(() => setCopied(false), 1500);
				});
			}}
		>
			{copied ? (
				<Check className="mr-1.5 h-3.5 w-3.5" />
			) : (
				<Copy className="mr-1.5 h-3.5 w-3.5" />
			)}
			{copied ? "Copied" : "Copy prompt"}
		</Button>
	);
}

