/**
 * Auto-provision a private personal organization for every newly created user.
 *
 * Mirrors the "filing cabinet" model: each user gets their own private org
 * (their data) which template agents (e.g. examples/personal-finance) can be
 * installed into. Without this, a user landing on the app has no workspace
 * to receive auto-installed agents or per-user mirrored schemas.
 */

import { slugify as slugifyBase } from "@lobu/core";
import { getDb } from "../db/client";
import { RESERVED_PATHS_SET } from "../utils/reserved";
import { generateSecureToken } from "./oauth/utils";
import { provisionMemberAndCoreIdentities } from "./subject-identities";
import { recordConfigChangeEvent } from "../utils/insert-event";
import logger from "../utils/logger";

interface UserLike {
	id: string;
	email?: string | null;
	name?: string | null;
	username?: string | null;
}

// Reserved owner-slug names. Re-exports the canonical set from utils/reserved
// (which is a superset of the DB `org_slug_not_reserved` CHECK constraint in
// 20260420120000_extend_reserved_org_slugs.sql). Inserts that hit a DB-reserved
// slug raise a constraint violation, so the candidate-derivation layer must
// avoid them up front; extra app-level entries are defense-in-depth against
// route-collision squatting.
export const RESERVED_SLUGS = RESERVED_PATHS_SET;

const MAX_SLUG_LENGTH = 48;
const MAX_COLLISION_ATTEMPTS = 100;
// Namespace for pg_advisory_xact_lock(key1, key2). Kept in the signed int32
// range required by PostgreSQL's two-key advisory lock overload.
const PERSONAL_ORG_LOCK_NAMESPACE = 0x706f7267; // "porg"

type Sql = ReturnType<typeof getDb>;

// Org slugs strip diacritics (NFKD) and cap length so they stay route-safe.
export function slugify(input: string): string {
	return slugifyBase(input, { normalize: true, maxLength: MAX_SLUG_LENGTH });
}

export function deriveSlugCandidate(user: UserLike): string {
	const candidates = [user.username, user.name, user.email?.split("@")[0]];
	for (const raw of candidates) {
		if (!raw) continue;
		const s = slugify(raw);
		if (s) return s;
	}
	return `user-${user.id.slice(0, 8).toLowerCase()}`;
}

async function findAvailableSlug(base: string, sql: Sql): Promise<string> {
	const safeBase = RESERVED_SLUGS.has(base) ? `${base}-1` : base;
	let candidate = safeBase;
	for (let attempt = 0; attempt < MAX_COLLISION_ATTEMPTS; attempt++) {
		if (!RESERVED_SLUGS.has(candidate)) {
			const rows = await sql`
        SELECT 1 FROM "organization" WHERE slug = ${candidate} LIMIT 1
      `;
			if (rows.length === 0) return candidate;
		}
		candidate = `${safeBase}-${attempt + 2}`;
	}
	// Last-resort suffix — astronomically unlikely to reach this branch.
	return `${safeBase}-${generateSecureToken(4)
		.toLowerCase()
		.replace(/[^a-z0-9]/g, "")}`;
}

interface EnsureResult {
	organizationId: string;
	slug: string;
	created: boolean;
}

export function personalOrgLockKey(userId: string): number {
	let hash = 0x811c9dc5;
	for (let i = 0; i < userId.length; i++) {
		hash ^= userId.charCodeAt(i);
		hash = Math.imul(hash, 0x01000193);
	}
	return hash | 0;
}

async function lockPersonalOrgForUser(userId: string, sql: Sql): Promise<void> {
	await sql`
    SELECT pg_advisory_xact_lock(
      ${PERSONAL_ORG_LOCK_NAMESPACE},
      ${personalOrgLockKey(userId)}
    )
  `;
}

export async function findExistingPersonalOrg(
	userId: string,
	sql: Sql,
): Promise<{ id: string; slug: string; name: string } | null> {
	// Idempotency: an org tagged with this user.id in metadata is already this
	// user's personal one. Re-running the hook (e.g. after a transient failure)
	// is a no-op. The ORDER BY keeps resolution deterministic if legacy data ever
	// contains duplicates.
	// organization.metadata is `text` storing JSON; cast to jsonb and use ->>
	// instead of LIKE so a userId containing % or _ can't match unintended rows.
	const existing = await sql`
    SELECT id, slug, name FROM "organization"
    WHERE metadata IS NOT NULL
      AND (metadata::jsonb)->>'personal_org_for_user_id' = ${userId}
    ORDER BY "createdAt" ASC, id ASC
    LIMIT 1
  `;
	if (existing.length === 0) return null;
	return existing[0] as { id: string; slug: string; name: string };
}

export async function ensurePersonalOrganization(
	user: UserLike,
): Promise<EnsureResult> {
	const sql = getDb();
	let result: EnsureResult | null = null;

	await sql.begin(async (tx) => {
		await lockPersonalOrgForUser(user.id, tx);

		const existing = await findExistingPersonalOrg(user.id, tx);
		if (existing) {
			result = {
				organizationId: existing.id,
				slug: existing.slug,
				created: false,
			};
			return;
		}

		const baseSlug = deriveSlugCandidate(user);
		const slug = await findAvailableSlug(baseSlug, tx);
		const orgId = `org_${generateSecureToken(8)}`;
		const memberId = `member_${generateSecureToken(8)}`;
		const orgName = user.name?.trim() || user.email?.split("@")[0] || slug;
		const metadata = JSON.stringify({ personal_org_for_user_id: user.id });

		await tx`
      INSERT INTO "organization" (id, name, slug, visibility, metadata, "createdAt")
      VALUES (${orgId}, ${orgName}, ${slug}, 'private', ${metadata}, NOW())
    `;
		await tx`
      INSERT INTO "member" (id, "userId", "organizationId", role, "createdAt")
      VALUES (${memberId}, ${user.id}, ${orgId}, 'owner', NOW())
    `;

		result = { organizationId: orgId, slug, created: true };
	});

	const finalResult = result as EnsureResult | null;
	if (!finalResult) {
		throw new Error(
			"Personal organization transaction did not produce a result",
		);
	}

	// A workspace with no audit trail of its own creation is a gap: `events` is
	// the workspace's history, and the first thing that ever happened to it was
	// being created. Only on `created` — this function is also the login path
	// for every existing personal org, and re-recording there would append a
	// duplicate row on every sign-in. Fire-and-forget, like every other config
	// audit write; a dropped row is logged, never fatal to provisioning.
	if (finalResult.created) {
		recordConfigChangeEvent({
			organizationId: finalResult.organizationId,
			resourceKind: "organization",
			resourceId: finalResult.organizationId,
			op: "created",
			summary: `Workspace '${finalResult.slug}' created`,
			state: { slug: finalResult.slug, visibility: "private" },
			actorSource: "ui",
			createdBy: user.id,
		});
	}

	// Mirror the personal org slug onto the user's username when unset. The
	// frontend resolves a user's home org from session.user.username
	// (personalOrgSlug); having it set means the home route can route to the
	// personal org synchronously instead of waiting on the `/api/organizations`
	// fetch. Non-fatal and idempotent (only fills a null username); the NOT
	// EXISTS guard avoids colliding with another user's username. Runs for both
	// newly created and pre-existing personal orgs so legacy users self-heal on
	// their next login.
	try {
		await sql`
      UPDATE "user"
      SET username = ${finalResult.slug}
      WHERE id = ${user.id}
        AND username IS NULL
        AND NOT EXISTS (
          SELECT 1 FROM "user" u2
          WHERE u2.username = ${finalResult.slug} AND u2.id <> ${user.id}
        )
    `;
	} catch (error) {
		console.error("[Auth] Failed to set username for personal org:", {
			userId: user.id,
			slug: finalResult.slug,
			error: String(error),
		});
	}

	// Provision the $member entity + core identifiers (auth_user_id, email)
	// outside the transaction. ensureMemberEntity uses createEntity which
	// manages its own transaction and seeds the $member entity type if absent.
	// Failures here shouldn't roll back the org creation — the user has a
	// valid org, identity rows can be backfilled later. Run this for both newly
	// created and pre-existing personal orgs; the helper is idempotent.
	if (user.email) {
		try {
			await provisionMemberAndCoreIdentities(finalResult.organizationId, {
				userId: user.id,
				email: user.email,
				name: user.name,
			});
		} catch (error) {
			// Drift risk: the personal org + member row exist, but without the
			// $member + auth:signup claim the user resolves to nothing in the authz
			// gate. Structured to correlate with the drift detector; non-fatal so a
			// failed identity write can't break org creation (it's retried on the
			// next call — the helper is idempotent).
			logger.error(
				{
					err: error,
					event: "member_claim_drift",
					hook: "personalOrgProvisioning",
					organizationId: finalResult.organizationId,
					userId: user.id,
				},
				"[Auth] Failed to provision $member entity for personal org",
			);
		}
	}

	return finalResult;
}

/**
 * `events` is the workspace's history, and the first thing that ever happened
 * to a workspace is being created — so provisioning records a config-audit row
 * for it. `ensurePersonalOrganization` is also the login path for every
 * existing personal org, so the row must be written exactly once, on create.
 */

import { beforeEach, describe, expect, it } from "vitest";
import { generateSecureToken } from "../../../auth/oauth/utils";
import { ensurePersonalOrganization } from "../../../auth/personal-org-provisioning";
import { cleanupTestDatabase, getTestDb } from "../../setup/test-db";

async function seedUser(name: string): Promise<{ id: string; email: string }> {
	const id = `user_${generateSecureToken(6)}`;
	const email = `${id}@test.local`;
	const sql = getTestDb();
	await sql`
    INSERT INTO "user" (id, name, email, "emailVerified", "createdAt", "updatedAt")
    VALUES (${id}, ${name}, ${email}, true, NOW(), NOW())
  `;
	return { id, email };
}

async function readCreationEvents(organizationId: string) {
	const sql = getTestDb();
	return await sql`
    SELECT title, origin_type, created_by, metadata, payload_data
    FROM events
    WHERE organization_id = ${organizationId}
      AND metadata->>'resource_kind' = 'organization'
    ORDER BY id
  `;
}

/** The write is fire-and-forget, so give the retry wrapper a beat to land. */
async function settle(): Promise<void> {
	await new Promise((resolve) => setTimeout(resolve, 250));
}

describe("ensurePersonalOrganization workspace-created event", () => {
	beforeEach(async () => {
		await cleanupTestDatabase();
	});

	it("records one config-audit row naming the new workspace", async () => {
		const { id, email } = await seedUser("Event Me");
		const result = await ensurePersonalOrganization({ id, email, name: "Event Me" });
		expect(result.created).toBe(true);
		await settle();

		const rows = await readCreationEvents(result.organizationId);
		expect(rows).toHaveLength(1);
		expect(rows[0].title).toBe(`Workspace '${result.slug}' created`);
		expect(rows[0].origin_type).toBe("config_organization_created");
		expect(rows[0].created_by).toBe(id);
		expect(rows[0].metadata.category).toBe("config");
		expect(rows[0].metadata.op).toBe("created");
		expect(rows[0].payload_data.state.slug).toBe(result.slug);
	});

	it("does not append a second row when an existing user signs in again", async () => {
		const { id, email } = await seedUser("Returning User");
		const first = await ensurePersonalOrganization({ id, email, name: "Returning User" });
		await settle();

		// Same call, same user: this is the login path, not a new workspace.
		const second = await ensurePersonalOrganization({ id, email, name: "Returning User" });
		expect(second.created).toBe(false);
		expect(second.organizationId).toBe(first.organizationId);
		await settle();

		const rows = await readCreationEvents(first.organizationId);
		expect(rows).toHaveLength(1);
	});
});

/**
 * Redaction for config-change audit snapshots (`metadata.category='config'`
 * events). Mutation payloads can carry resolved secret material — platform
 * config arrives from `lobu apply` with `$VAR`/`secret()` refs already
 * resolved to plaintext — so every state snapshot is passed through here
 * before it is persisted into `events.payload_data`.
 *
 * The denylist walk and sentinel live in @lobu/core (`secret-redaction`),
 * shared with the CLI's manifest hashing; this module adds the per-kind
 * rules that only the server needs.
 */

import { deepRedactSecrets, REDACTED_SENTINEL } from '@lobu/core';

export { REDACTED_SENTINEL };

/**
 * Resource kinds for config-change events. Mirrors the CLI apply DiffRow
 * `kind` union so per-kind counts and per-resource rows line up in the
 * deployments UI without a mapping table.
 */
export type ConfigResourceKind =
  | 'organization'
  | 'agent'
  | 'agent-settings'
  | 'platform'
  | 'entity-type'
  | 'relationship-type'
  | 'behavior'
  | 'connector-definition'
  | 'auth-profile'
  | 'connection'
  | 'feed'
  | 'inference-provider'
  | 'provider-key';

/**
 * Redact a post-change state snapshot before persisting it.
 *
 * On top of the deep-walk denylist, per-kind hard rules cover fields whose
 * secret-ness the key name can't reveal:
 *  - `auth-profile`: `credentials` replaced wholesale (connector-defined keys).
 *  - `platform` / `connection`: `config` deep-walked (denylist) — platform
 *    config values arrive as resolved plaintext from the CLI.
 *  - `inference-provider`: `apiKey`/`api_key` (already denylisted; kept
 *    explicit as a guarantee, not a heuristic).
 *  - `provider-key`: never snapshotted — state is forced to null.
 */
export function redactConfigState(
  kind: ConfigResourceKind,
  state: Record<string, unknown> | null
): Record<string, unknown> | null {
  if (state === null) return null;
  if (kind === 'provider-key') return null;

  const redacted = deepRedactSecrets(state) as Record<string, unknown>;

  if (kind === 'auth-profile' && redacted.credentials != null) {
    redacted.credentials = REDACTED_SENTINEL;
  }
  return redacted;
}

import { HttpResponse, http } from "msw";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { renderRoute } from "@/test/render";

const CLAUDE_DESKTOP = {
	id: "claude-desktop",
	kind: "mcp",
	title: "Claude Desktop",
	registrationGroupKey: "claude-desktop",
	status: "connected",
	authState: "authorized",
	lastSeenAt: 1,
};

// Per-test so the empty workspace can be exercised — the fresh-install case is
// the one that regressed. Reassigned before render, never mid-render.
let mockClients: unknown[] = [CLAUDE_DESKTOP];

// The landing page's connected-apps section is the old connectors "Agents"
// inventory filter, which moved here when Agents became its own nav section.
vi.mock("@/lib/api/clients", () => ({
	useConnectedClients: () => ({ data: mockClients }),
}));

beforeEach(() => {
	mockClients = [CLAUDE_DESKTOP];
});

describe("agents landing page", () => {
	it("lists managed agents and connected apps and offers the onboarding prompt", async () => {
		// getPathScope reads window.location, so pin it to the route under test.
		const previousUrl = window.location.pathname + window.location.search;
		window.history.replaceState({}, "", "/test-org/agents");
		let unmount: (() => void) | undefined;
		try {
			const result = await renderRoute(
				"/test-org/agents",
				{
					authenticated: true,
					extraHandlers: [
					http.post("*/api/:slug/resolve_path", () =>
						HttpResponse.json({
							workspace: {
								id: "org-1",
								slug: "test-org",
								name: "Test Org",
								type: "organization",
							},
							segments: [],
							path: [],
							entity: null,
							children: [],
							siblings: [],
							bootstrap: null,
						}),
					),
					http.get("*/api/organizations", () =>
						HttpResponse.json({
							organizations: [
								{
									id: "org-1",
									name: "Test Org",
									slug: "test-org",
									logo: null,
									description: null,
									created_at: "2026-01-01T00:00:00.000Z",
									is_member: true,
									visibility: "private",
								},
							],
						}),
					),
					http.get("*/api/:slug/agents", () =>
						HttpResponse.json({
							agents: [
								{
									agentId: "agent-a",
									name: "Alpha",
									description: undefined,
									owner: { platform: "web", userId: "user-1" },
									createdAt: 1,
									connectionCount: 2,
									activeConnectionCount: 1,
									clientCount: 0,
									behaviorCount: 1,
									userCount: 3,
									platforms: [],
									providers: [],
									status: "active",
								},
							],
						}),
					),
				],
			});
			unmount = result.unmount;

			// No page header — the page opens straight into the chips + list,
			// like the connectors page.
			expect(result.queryByRole("heading", { name: "Agents" })).toBeNull();
			// Managed roster row links into the agent's chat.
			const alpha = await result.findByRole("link", { name: /Alpha/ });
			expect(alpha).toHaveAttribute("href", "/test-org/agents/agent-a/chat");
			// Connected external agent (moved from the connectors Agents filter).
			expect(await result.findByText("Claude Desktop")).toBeInTheDocument();
			// The build CTA links to the new-agent form.
			expect(
				result.getAllByText("Build a managed agent").length,
			).toBeGreaterThan(0);

			// One filterable list, connectors-style: the Managed chip narrows to
			// the roster, Connected to the apps, All restores both.
			expect(
				await result.findByRole("button", { name: "Managed" }),
			).toHaveAttribute("aria-pressed", "false");
			result.getByRole("button", { name: "Connected" });
			expect(
				result.queryByRole("heading", { name: "Connected apps" }),
			).toBeNull();
			expect(
				result.queryByRole("heading", { name: "Managed agents" }),
			).toBeNull();

			result.getByRole("button", { name: "Managed" }).click();
			expect(
				await result.findByRole("link", { name: /Alpha/ }),
			).toBeInTheDocument();
			expect(result.queryByText("Claude Desktop")).toBeNull();

			result.getByRole("button", { name: "Connected" }).click();
			expect(
				await result.findByText("Claude Desktop"),
			).toBeInTheDocument();
			expect(result.queryByRole("link", { name: /Alpha/ })).toBeNull();
		} finally {
			unmount?.();
			window.history.replaceState({}, "", previousUrl);
		}
	}, 30_000);

	it("offers a copy-prompt button for connecting an existing agent", async () => {
		// getPathScope reads window.location, so pin it to the route under test.
		const previousUrl = window.location.pathname + window.location.search;
		window.history.replaceState({}, "", "/test-org/agents");
		let unmount: (() => void) | undefined;
		try {
			const result = await renderRoute("/test-org/agents", {
				authenticated: true,
				extraHandlers: [
				http.post("*/api/:slug/resolve_path", () =>
					HttpResponse.json({
						workspace: {
							id: "org-1",
							slug: "test-org",
							name: "Test Org",
							type: "organization",
						},
						segments: [],
						path: [],
						entity: null,
						children: [],
						siblings: [],
						bootstrap: null,
					}),
				),
				http.get("*/api/organizations", () =>
					HttpResponse.json({
						organizations: [
							{
								id: "org-1",
								name: "Test Org",
								slug: "test-org",
								logo: null,
								description: null,
								created_at: "2026-01-01T00:00:00.000Z",
								is_member: true,
								visibility: "private",
							},
						],
					}),
				),
				http.get("*/api/:slug/agents", () =>
					HttpResponse.json({ agents: [] }),
				),
			],
		});
			unmount = result.unmount;

			expect(
				await result.findByRole("button", {
					name: "Copy prompt to bring your agent",
				}),
			).toBeInTheDocument();
			expect(
				result.getByRole("link", { name: "Build a managed agent" }),
			).toHaveAttribute("href", "/test-org/agents/new");
		} finally {
			unmount?.();
			window.history.replaceState({}, "", previousUrl);
		}
	}, 30_000);

	it("points a fresh workspace at the MCP endpoint instead of blaming a filter", async () => {
		// A brand-new install: no managed agents, nothing connected. Filter chips
		// only render when more than one kind exists, so this page has none — any
		// "try another filter" copy sends people hunting for a control that is
		// not on the page.
		mockClients = [];
		const previousUrl = window.location.pathname + window.location.search;
		window.history.replaceState({}, "", "/test-org/agents");
		let unmount: (() => void) | undefined;
		try {
			const result = await renderRoute("/test-org/agents", {
				authenticated: true,
				extraHandlers: [
					http.post("*/api/:slug/resolve_path", () =>
						HttpResponse.json({
							workspace: {
								id: "org-1",
								slug: "test-org",
								name: "Test Org",
								type: "organization",
							},
							segments: [],
							path: [],
							entity: null,
							children: [],
							siblings: [],
							bootstrap: null,
						}),
					),
					http.get("*/api/organizations", () =>
						HttpResponse.json({
							organizations: [
								{
									id: "org-1",
									name: "Test Org",
									slug: "test-org",
									logo: null,
									description: null,
									created_at: "2026-01-01T00:00:00.000Z",
									is_member: true,
									visibility: "private",
								},
							],
						}),
					),
					http.get("*/api/:slug/agents", () =>
						HttpResponse.json({ agents: [] }),
					),
				],
			});
			unmount = result.unmount;

			// Wait for the settled page before asserting on absence, or an empty
			// first paint would pass every queryBy below on its own.
			await result.findByRole("button", {
				name: "Copy prompt to bring your agent",
			});

			// No chips are rendered, so nothing may claim a filter hid the rows.
			// Asserted before the offer link so a regression in the copy fails
			// here rather than being masked by the missing-row failure.
			expect(result.queryByRole("button", { name: "Managed" })).toBeNull();
			expect(result.queryByRole("button", { name: "Connected" })).toBeNull();
			expect(result.queryByText(/match this filter/i)).toBeNull();
			expect(result.queryByText(/another filter/i)).toBeNull();

			// The setup offer is the page's answer to an empty workspace, and it
			// links at the shared MCP-client instructions on the connectors side.
			const offer = await result.findByRole("link", { name: /MCP client/ });
			expect(offer).toHaveAttribute(
				"href",
				"/test-org/connectors/app/mcp-client",
			);
		} finally {
			unmount?.();
			window.history.replaceState({}, "", previousUrl);
		}
	}, 30_000);
});

