/**
 * Fetch reusable Behavior templates from the global catalog. Served from the
 * bundled defaults unless `LOBU_CATALOG_URIS` overrides them (env wins outright).
 */
export function useBehaviorCatalog() {
  return useQuery({
    queryKey: ['behavior-catalog'],
    queryFn: async () => {
      const result = await apiCall<{
        catalogs?: { behaviors?: { entries?: BehaviorCatalogTemplate[] } };
      }>('manage_catalog', { action: 'list_catalog', kinds: ['behaviors'] });
      return result.catalogs?.behaviors?.entries ?? [];
    },
    staleTime: 60000,
  });
}

/**
 * Fetch Behaviors for an entity. When entityId is undefined, fetch across all
 * entities in the organization.
 */
export function useBehaviorsList(
  organizationId: string | undefined,
  entityId?: number,
  options?: { includeDetails?: boolean },
) {
  return useQuery({
    queryKey: ['behaviors-list', organizationId, entityId, options?.includeDetails ?? true],
    queryFn: async () => {
      const result = await apiCall<{ behaviors: BehaviorRecord[] }>('manage_behaviors', {
        action: 'list',
        entity_id: entityId, // undefined = all entities
        status: 'active',
        include_details: options?.includeDetails ?? true,
      });
      return result.behaviors || [];
    },
    // Only requires organizationId - entityId is optional
    enabled: !!organizationId,
    staleTime: 30000,
  });
}

