	path: string,
	orgContext?:
		| { organizationId?: string | null; slug?: string | null }
		| string
		| null,
	options?: { includeBootstrap?: boolean },
) {
	const ctx = normalizeOrgContext(orgContext);
	const orgSelector =
		ctx.organizationId || ctx.slug ? resolveOrgSelector(ctx) : undefined;
	const normalizedPath = normalizeResolvedPathInput(path);
	// Key on slug-OR-orgId (whichever's set) but not both — slug uniquely
	// identifies the org, and orgId may arrive asynchronously after first
	// mount once `/api/organizations` resolves. Keying on both meant the
	// initial render fired one request with `organizationId=undefined` and
	// refetched moments later when orgId materialised.
	return {
		queryKey: [
			"resolve-path",
			normalizedPath,
			ctx.slug || ctx.organizationId,
			options?.includeBootstrap ?? false,
		] as const,
		queryFn: async () => {
			const result = await apiCall<ResolvePathResult>(
				"resolve_path",
				{
					path: normalizedPath,
					include_bootstrap: options?.includeBootstrap ?? false,
				},
				orgSelector,
			);
			return result;
		},
		staleTime: 300000,
		normalizedPath,
	};
}

