  orgId: string;
  ownerId: string;
  orgSlug: string;
  token: string;
  memberToken: string;
  canonicalDealId: number;
  mergedDealId: number;
}

async function seedFixture(): Promise<Fixture> {
  const org = await createTestOrganization({ name: 'Resolve Contract Org', slug: 'resolve-contract' });
