  sql: DbClient,
  workspace: ResolvedWorkspace,
  userId: string | null
): Promise<WorkspaceCounts> {
  return workspace.type === 'organization'
    ? fetchWorkspaceCounts(sql, workspace.id, userId)
    : Promise.resolve(EMPTY_WORKSPACE_COUNTS);
}

