1	/**
2	 * Tool: resolve_path
3	 *
4	 * Resolves a URL path like /acme/company/spotify into
5	 * workspace + entity details by walking the entity hierarchy.
6	 *
7	 * URL pattern: /:owner/entity-type/entity-slug/...
8	 */
9	
10	import * as Sentry from '@sentry/node';
11	import { type Static, Type } from '@sinclair/typebox';
12	import { getDb } from '../db/client';
13	import type { Env } from '../index';
14	import { feedLinkedToBusinessEntitySql } from '../authz/channel-about';
15	import { entityLinkMatchSql } from '../utils/content-search';
16	import {
17	  type DataSourceContext,
18	  type DataSourceInput,
19	  executeDataSources,
20	} from '../utils/execute-data-sources';
21	import { ToolUserError } from '../utils/errors';
22	import { resolveMemberSchemaFieldsFromSchema } from '../utils/member-entity-type';
23	import { stripMemberEmailsFromRows } from '../utils/member-redaction';
24	import {
25	  derivedRowName,
26	  derivedRowSlug,
27	  getEntityCountsByTypes,
28	  queryDerivedEntityView,
29	} from '../utils/entity-management';
30	import { buildDefaultEntityTemplate } from '../utils/default-entity-template';
31	import { measureColumns as inferMeasureColumns } from '../utils/infer-measures';
32	import { RESERVED_PATHS_SET } from '../utils/reserved';
33	import { getWorkspaceProvider } from '../workspace';
34	import { isAdminOrOwnerRole } from './access-control';
35	import { MEMBER_ENTITY_TYPE_SLUG } from './constants';
36	import type { ToolContext } from './registry';
37	import { withValidatedArgs } from './validate-args';
38	
39	export const ResolvePathSchema = Type.Object({
40	  path: Type.String({
41	    description: 'URL path like /acme/company/spotify (query string optional)',
42	    minLength: 1,
43	  }),
44	  include_bootstrap: Type.Optional(
45	    Type.Boolean({
46	      description:
47	        'When true, includes shared bootstrap data for sidebar and overview pages in the response',
48	      default: false,
49	    })
50	  ),
51	});
52	
53	type ResolvePathArgs = Static<typeof ResolvePathSchema>;
54	
55	export const ResolvedWorkspaceSchema = Type.Object({
56	  slug: Type.String(),
57	  type: Type.Union([Type.Literal('user'), Type.Literal('organization')]),
58	  id: Type.String(),
59	  name: Type.Union([Type.String(), Type.Null()]),
60	});
61	export type ResolvedWorkspace = Static<typeof ResolvedWorkspaceSchema>;
62	
63	export const ResolvedPathEntitySchema = Type.Object({
64	  id: Type.Integer(),
65	  entity_type: Type.String(),
66	  slug: Type.String(),
67	  name: Type.String(),
68	});
69	export type ResolvedPathEntity = Static<typeof ResolvedPathEntitySchema>;
70	
71	const ViewTemplateTabSchema = Type.Object({
72	  tab_name: Type.String(),
73	  tab_order: Type.Integer(),
74	  json_template: Type.Record(Type.String(), Type.Unknown()),
75	  version: Type.Integer(),
76	  version_id: Type.Integer(),
77	  template_data: Type.Union([
78	    Type.Record(Type.String(), Type.Array(Type.Unknown())),
79	    Type.Null(),
80	  ]),
81	});
82	type ViewTemplateTab = Static<typeof ViewTemplateTabSchema>;
83	
84	const MergedRecordSchema = Type.Object({
85	  id: Type.Integer(),
86	  name: Type.String(),
87	  slug: Type.String(),
88	  metadata: Type.Record(Type.String(), Type.Unknown()),
89	  merged_at: Type.String(),
90	  can_unmerge: Type.Boolean(),
91	});
92	
93	// ResolvedEntityDetails = ResolvedPathEntity + detail fields. TypeBox has no
94	// `extends`; compose via intersect so the derived type stays a single source.
95	export const ResolvedEntityDetailsSchema = Type.Intersect([
96	  ResolvedPathEntitySchema,
97	  Type.Object({
98	    parent_id: Type.Union([Type.Integer(), Type.Null()]),
99	    metadata: Type.Record(Type.String(), Type.Unknown()),
100	    /** Per-field human-ownership markers (key present = a human set that field).
101	     *  Lets the UI badge owned fields + show the correction note. */
102	    field_controls: Type.Record(
103	      Type.String(),
104	      Type.Object({
105	        note: Type.Optional(Type.Union([Type.String(), Type.Null()])),
106	        set_by: Type.Optional(Type.Union([Type.String(), Type.Null()])),
107	        set_at: Type.Optional(Type.String()),
108	      })
109	    ),
110	    json_template: Type.Union([Type.Record(Type.String(), Type.Unknown()), Type.Null()]),
111	    json_template_version: Type.Union([Type.Integer(), Type.Null()]),
112	    template_data: Type.Union([
113	      Type.Record(Type.String(), Type.Array(Type.Unknown())),
114	      Type.Null(),
115	    ]),
116	    tabs: Type.Array(ViewTemplateTabSchema),
117	    created_at: Type.String(),
118	    // Stats
119	    total_content: Type.Integer(),
120	    active_connections: Type.Integer(),
121	    behaviors_count: Type.Integer(),
122	    // Derived ("view") entity: synthesized from the type's `backing_sql` filtered
123	    // to this slug, not a stored `entities` row. `metadata` holds the full view
124	    // row; `measure_columns` are its aggregate columns. Stored entities omit both.
125	    is_derived: Type.Optional(Type.Boolean()),
126	    measure_columns: Type.Optional(Type.Array(Type.String())),
127	    /** Tombstoned source rows currently forwarded to this canonical entity. */
128	    merged_records: Type.Optional(Type.Array(MergedRecordSchema)),
129	  }),
130	]);
131	export type ResolvedEntityDetails = Static<typeof ResolvedEntityDetailsSchema>;
132	
133	export const ChildEntitySchema = Type.Object({
134	  id: Type.Integer(),
135	  entity_type: Type.String(),
136	  slug: Type.String(),
137	  name: Type.String(),
138	  market: Type.Union([Type.String(), Type.Null()]),
139	  content_count: Type.Integer(),
140	});
141	export type ChildEntity = Static<typeof ChildEntitySchema>;
142	
143	interface ResolvedEntityRow {
