158	  name: Type.String(),
159	  content_count: Type.Integer(),
160	});
161	export type SiblingEntity = Static<typeof SiblingEntitySchema>;
162	
163	const BootstrapEntityTypeSummarySchema = Type.Object({
164	  id: Type.Integer(),
165	  slug: Type.String(),
166	  name: Type.String(),
167	  description: Type.Union([Type.String(), Type.Null()]),
168	  icon: Type.Union([Type.String(), Type.Null()]),
169	  color: Type.Union([Type.String(), Type.Null()]),
